-- Arabic display translations of existing published source descriptions.
-- Preserve reviewed nonempty translations and all original source text.
update public.beans b set description_ar=t.description_ar from (values
('Colombia El Mesón – Filter','معالجة مغسولة، بتخمير لمدة ٢٤ ساعة وتجفيف تحت الشمس لمدة ٢٠ يومًا، على ارتفاع ١٦٥٠–١٧٠٠ متر. إيحاءات المحمصة: البرتقال الدموي والشاي الأخضر والتوت الأزرق. يتوفر بأكياس ٢٥٠ غرامًا وكيلوغرام واحد.'),
('Colombia Hermides Meneses','الإيحاءات بحسب كوراسو: زهور وبرتقال دموي وعشبة الليمون وتوت أحمر ومكسرات حلوة.'),
('El Salvador Don Jaime','الإيحاءات بحسب كوراسو: زهور وبرقوق وفاكهة العاطفة وقراصيا وفول سوداني وشوكولاتة. الارتفاع المنشور ١٤٠٠–١٥٠٠ متر. يتوفر بأكياس ٢٥٠ غرامًا وكيلوغرام واحد.'),
('El Salvador Emerson Vasquez Pacamara','الإيحاءات بحسب كوراسو: زهور وقشر برتقال ويوسفي أخضر وكرز وبرتقال دموي وتوت أسود. الارتفاع المنشور ١٥٠٠–١٦٠٠ متر. يتوفر بأكياس ٢٥٠ غرامًا وكيلوغرام واحد.'),
('Ethiopia Kello Lalesa – Filter','معالجة مغسولة في محطة لاليسا. إيحاءات المحمصة: ياسمين ومربى الخوخ وبرتقال. يتوفر بأكياس ٢٥٠ غرامًا وكيلوغرام واحد.'),
('Finca Tamana Caturron','إيحاءات عشبية وزهرية مع فلفل هابانيرو وبابايا وفلفل حلو وفاكهة استوائية. قطف يدوي انتقائي، وتخمير لمدة ٢٤ ساعة، وغسل في مطحنة موفرة للماء، وتجفيف لمدة ٢٠–٣٠ يومًا في مجففات مقوسة. كيس حبوب كامل بوزن ٢٥٠ غرامًا. السعر المسجل وقت جمع المصدر ٢٤٠ كرونة نرويجية؛ لا يمثل سعرًا حاليًا. لم يُذكر الارتفاع أو مستوى التحميص.'),
('Gachatha','إيحاءات الكشمش الأسود والتوت الأسود والزبيب، ونكهات فاكهية مكثفة مميزة لسلالات إس إل التقليدية. كيس حبوب كامل بوزن ٢٥٠ غرامًا. السعر المسجل وقت جمع المصدر ٢٢٥ كرونة نرويجية؛ لا يمثل سعرًا حاليًا. لم تُذكر درجة التحميص في صفحة المصدر.'),
('Indonesia Frinsa Estate Weninggalih','الإيحاءات بحسب كوراسو: برقوق ومانجو مجففة وحمضيات وشاي صيني وكاجو. المعالجة المنشورة مغسولة بالكامل، والارتفاع ١٣٠٠–١٥٠٠ متر. يتوفر بأكياس ٢٥٠ غرامًا وكيلوغرام واحد.'),
('Kenya Gatomboya AB','الإيحاءات بحسب كوراسو: زهور وجريب فروت وكشمش أحمر وتفاح وسكر قصب وشاي أسود.'),
('Kenya Thunguri AA – Filter','من تعاونية مزارعي كيبيريغوي، محطة ثونغوري. مغسول بالكامل ومجفف على أسرّة مرتفعة. إيحاءات المحمصة: كشمش أسود ناضج وكركديه وشاي أسود. يتوفر بأكياس ٢٥٠ غرامًا وكيلوغرام واحد.'),
('Los Pirineos Pacamara','إيحاءات توت أحمر لاذع وفاكهة ذات نواة وشوكولاتة داكنة، مع حموضة واضحة البنية. الارتفاع المنشور ١١٠٠–١٤٠٠ متر. كيس حبوب كامل بوزن ٢٥٠ غرامًا. السعر المسجل وقت جمع المصدر ٢٢٥ كرونة نرويجية؛ لا يمثل سعرًا حاليًا. لم تُذكر درجة التحميص.'),
('Rwanda Mbilima Soil Project Lot.0704','الإيحاءات بحسب كوراسو: زهور وتفاح أحمر ويوسفي وشاي آسام وعسل. الارتفاع المنشور ١٨٠٠–٢١٠٠ متر.')
) as t(name_en,description_ar) where b.name_en=t.name_en and b.is_published and not b.requires_review and nullif(trim(b.description_ar),'') is null;
